seo_schema:
{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "वरुण विहार योजना में आवेदन की आखिरी तारीख क्या है?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "पहले चरण के 2,847 भूखंडों का पंजीकरण 24 सितंबर से 24 अक्टूबर 2026 तक registration.ldalucknow.in पर चल रहा है।"
      }
    },
    {
      "@type": "Question",
      "name": "वरुण विहार में भूखंड की कीमत कितनी है?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "एलडीए ने दर ₹2,800 प्रति वर्गफुट तय की है। 112.5 वर्ग मीटर का भूखंड करीब ₹33.9 लाख और 450 वर्ग मीटर का करीब ₹1.36 करोड़ का है। कॉर्नर/पार्क-फेसिंग और 12% फ्रीहोल्ड शुल्क अलग हैं।"
      }
    },
    {
      "@type": "Question",
      "name": "पंजीकरण के लिए कितना पैसा जमा करना होगा?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "₹1,100 की बुकलेट के बाद भूखंड की कीमत का 5% (आरक्षित वर्ग के लिए 2.5%) जमा करना होगा। 112.5 वर्ग मीटर के भूखंड के लिए यह करीब ₹1.7 लाख है।"
      }
    },
    {
      "@type": "Question",
      "name": "क्या एकमुश्त भुगतान करने पर कोई फायदा है?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "हां। 45 दिन में पूरा भुगतान करने पर 6%, 60 दिन में 5% और 90 दिन में 4% छूट मिलती है। भास्कर डिजिटल के अनुसार एकमुश्त भुगतान चुनने वालों की लॉटरी पहले निकलेगी।"
      }
    },
    {
      "@type": "Question",
      "name": "वरुण विहार लखनऊ में कहां है?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "आगरा–लखनऊ एक्सप्रेसवे के पास, सदर और सरोजिनी नगर तहसील में। योजना के उत्तर में आगरा–लखनऊ एक्सप्रेसवे और दक्षिण में फतेहगंज–मोहन रोड है।"
      }
    },
    {
      "@type": "Question",
      "name": "वरुण विहार में कौन-कौन से गांव हैं?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "एलडीए के अनुसार 12 गांव: भलिया, आदमपुर इंदवारा, बहरू, जलियामऊ, मदारपुर, इब्राहिमगंज, नकटौरा, गहलवारा, तेजकृष्ण खेड़ा, रेवरी, सकरा और डोना।"
      }
    },
    {
      "@type": "Question",
      "name": "पहले चरण में किन खंडों में भूखंड हैं?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "काशी खंड, कैलाश खंड फेज-1 और कैलाश खंड फेज-2 में कुल 2,847 भूखंड हैं — 112.5 वर्ग मीटर के 1,517, 162 के 460, 200 के 612, 288 के 68, 300 के 81 और 450 वर्ग मीटर के 109।"
      }
    },
    {
      "@type": "Question",
      "name": "वरुण विहार में कौन आवेदन कर सकता है?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "अमर उजाला के अनुसार 18 साल से ज्यादा उम्र का कोई भी व्यक्ति, जिसे पहले एलडीए या किसी आवास प्राधिकरण से भूखंड/मकान न मिला हो। पूरी शर्तें एलडीए की बुकलेट में दी गई हैं।"
      }
    }
  ]
}
